head.script:
scwin.gVar = {
    "cDisabled" : "",
    "cReadOnly" : "",
}



// 테스트 설명, 유효성 값 설정
//  - @spec 의 "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다." 는
//    브라우저 구현 차이에 대한 안내 문구로 확인 수단을 만들 수 없어 유효성에서 제외한다. (secret_E_onblur_1 / secret_E_onclick_1 선례)
//  - e 객체의 개별 속성(e.bubbles, e.relatedTarget, e.target 등)은 표준 DOM 이벤트 속성이라 개별 유효성으로 만들지 않는다.
//  - onFocusClass 는 클래스 추가 시점 확인을 위한 전제로만 고정 설정하며 속성 자체의 기능은 검증하지 않는다.
scwin.tData = {
    "description" : "[secret > E > onfocus]<br/>Secret 컴포넌트가 포커스를 받을 때 발생합니다.",
    "validation" : [
        "Secret 컴포넌트가 포커스를 받을 때 onfocus 이벤트가 발생합니다.",
        "이벤트 핸들러에 FocusEvent 객체 e 가 전달됩니다.",
        "disabled=true 또는 readOnly=true 인 경우 onfocus 이벤트가 발생하지 않습니다.",
        "onFocusClass 속성에 의해 클래스가 추가된 후 onfocus 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 코드값 1 = 미설정)
    con_disabled.setValue("1");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="target1 은 onFocusClass=onFocusClass (tc.css 에 배경 노랑으로 정의) 로 고정 설정되며, 재생성 직후 class 줄과 onfocus 핸들러 시점 class 줄을 비교해 클래스 추가 시점을 확인합니다.\n결과창 clear -> 조건 선택 후 Target 재생성 -> 바깥 영역을 클릭해 포커스를 해제한 뒤 target1 을 클릭하거나 Tab 키로 포커스를 이동합니다."', '', 'label1');

    // 조건 설정
    scwin.gVar["cDisabled"] = con_disabled.getText();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    let properties = {
        onFocusClass : "onFocusClass",
        disabled : scwin.gVar["cDisabled"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onfocus"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, eList);

    // 포커스 전 기준선 (클래스 추가 시점 판정의 대조값) - validation 4 판정 출력
    wf_body_bottom.getObj("scwin").setReturnValue("재생성 직후 class : " + target1.render.className + " / bg : " + target1.getStyle("background-color"));
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 테스트 샘플의 이벤트 처리 (포커스 획득) - validation 1, 2, 3, 4 판정 출력
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("disabled " + scwin.fn_disp(scwin.gVar["cDisabled"]) + " / readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + " -> onfocus 이벤트 발생 / class : " + target1.render.className + " / bg : " + target1.getStyle("background-color"));
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
